package tokenizer

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import java.time.temporal.TemporalAccessor
import scala.util.Try
import io.circe.Json
import scala.collection.immutable.LazyList

/**
 * TokenType Enum for converted tokens.
 */
sealed abstract class TokenType(val value: String)
object TokenType {
  case object STRING     extends TokenType("string")
  case object NUMERIC    extends TokenType("numeric")
  case object TEMPORAL   extends TokenType("temporal")
  case object STRUCTURED extends TokenType("structured")
  case object BINARY     extends TokenType("binary")
  case object NULL       extends TokenType("null")
}

/**
 * Immutable token representation.
 */
case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(newMeta: (String, Any)*): Token = {
    copy(metadata = metadata ++ newMeta.toMap)
  }
}

/**
 * Mutable batch of tokens.
 */
class MutableTokenBatch {
  private val _tokens = scala.collection.mutable.ListBuffer.empty[Token]
  private var _processed = false

  def tokens: Seq[Token] = _tokens.toSeq

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

/**
 * Trait for objects that can be converted to a token string.
 */
trait Tokenizable {
  def toToken: String
}

/**
 * Covariant container for items.
 */
class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector
  def getAll: Vector[T] = _items
  def mapTokens(func: T => String): List[String] = _items.map(func).toList
  def size: Int = _items.size
}

/**
 * Contravariant sink for receiving items.
 */
class TokenSink[-T] {
  private val _received = scala.collection.mutable.ListBuffer.empty[Any]
  def receive(item: T): Unit = {
    _received += item
  }
  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/**
 * Invariant handler for transformable values.
 */
class BivariantHandler[T](private var _value: T) {
  def get: T = _value
  def set(value: T): Unit = {
    _value = value
  }
  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

/**
 * Base trait for all tokenizers.
 */
trait BaseTokenizer[T] {
  def tokenize(value: T): Token
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = values.iterator.map(tokenize)
}

/**
 * Tokenizer for String and Byte Array types.
 */
class StringTokenizer(
    encoding: String = "utf-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Any] {
  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case b: Array[Byte] => new String(b, encoding)
      case s: String      => s
      case _              => value.toString
    }
    Token(normalizer(strValue), TokenType.STRING)
  }
}

/**
 * Tokenizer for numeric types with precision handling.
 */
class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {
  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case d: BigDecimal => s"%.${precision}f".format(d)
      case d: Double     => s"%.${precision}f".format(d)
      case f: Float      => s"%.${precision}f".format(f)
      case n: Int        => n.toString
      case n: Long       => n.toString
      case _             => value.toString
    }
    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

/**
 * Tokenizer for temporal types.
 */
class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[TemporalAccessor] {
  private val isoFormatter  = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: TemporalAccessor): Token = {
    val formatter = formatStr match {
      case Some(fmt) => DateTimeFormatter.ofPattern(fmt)
      case None =>
        value match {
          case _: LocalDateTime => isoFormatter
          case _: LocalDate     => dateFormatter
          case _                => isoFormatter
        }
    }
    Token(formatter.format(value), TokenType.TEMPORAL)
  }
}

/**
 * Universal Tokenizer with runtime type dispatch.
 */
class UniversalTokenizer {
  private val stringTokenizer   = new StringTokenizer()
  private val numericTokenizer  = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: Any): Token = value match {
    case null             => tokenizeNull
    case t: Tokenizable   => Token(t.toToken, TokenType.STRUCTURED)
    case s: String        => stringTokenizer.tokenize(s)
    case b: Array[Byte]   => stringTokenizer.tokenize(b)
    case n: Int           => numericTokenizer.tokenize(n)
    case n: Long          => numericTokenizer.tokenize(n)
    case n: Double        => numericTokenizer.tokenize(n)
    case n: Float         => numericTokenizer.tokenize(n)
    case n: BigDecimal    => numericTokenizer.tokenize(n)
    case d: LocalDateTime => temporalTokenizer.tokenize(d)
    case d: LocalDate     => temporalTokenizer.tokenize(d)
    case _ => Token(value.toString, TokenType.STRING, Map("fallback" -> true))
  }

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)
}

/**
 * Registry for managing token containers and handlers.
 */
class TokenRegistry[T] {
  private val _registry = scala.collection.mutable.Map.empty[String, TokenContainer[T]]
  private val _handlers = scala.collection.mutable.ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
